'use strict';
const DATA=JSON.parse(document.getElementById('content-data').textContent);
const KEY='crossSeaV6.cityAtlas';
let persistenceOK=true;
const emptyState=()=>({lang:'zh',photos:false,bookmarks:[],completed:[],notes:{},answers:{},compare:[]});
let state=emptyState();
try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw&&typeof raw==='object'){state={...state,...raw};state.lang=['zh','ja','dual'].includes(raw.lang)?raw.lang:'zh';state.notes=raw.notes&&typeof raw.notes==='object'&&!Array.isArray(raw.notes)?raw.notes:{};for(const k of ['bookmarks','completed','compare'])state[k]=Array.isArray(raw[k])?raw[k].filter(x=>typeof x==='string'):[];state.answers=raw.answers&&typeof raw.answers==='object'?raw.answers:{};}}catch{persistenceOK=false;}
const initialLanguage=new URLSearchParams(location.search).get('lang');
if(['zh','ja','dual'].includes(initialLanguage))state.lang=initialLanguage;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pair=(zh,ja)=>({zh,ja});
const plain=x=>typeof x==='string'?x:(x?.[state.lang==='ja'?'ja':'zh']||x?.zh||'');
const t=(zh,ja)=>state.lang==='ja'?ja:zh;
const dateLabel=x=>state.lang==='ja'?String(x).replace(/世纪/g,'世紀').replace(/约/g,'約'):String(x);
const bi=x=>typeof x==='string'?esc(x):state.lang==='dual'?`<span lang="zh-CN">${esc(x.zh)}</span><span class="sub" lang="ja">${esc(x.ja)}</span>`:`<span lang="${state.lang==='ja'?'ja':'zh-CN'}">${esc(plain(x))}</span>`;
const B=(zh,ja)=>bi(pair(zh,ja));
const indexes=Object.fromEntries(['places','events','people','studies','sources','routes','cases','images'].map(k=>[k,Object.fromEntries(DATA[k].map(x=>[x.id,x]))]));
const get=(type,id)=>indexes[type]&&Object.prototype.hasOwnProperty.call(indexes[type],id)?indexes[type][id]:undefined;
const cityname=c=>c==='xian'?pair('西安','西安'):pair('北京','北京');
const eraLabels={early:pair('史前·秦汉','先史・秦漢'),tang:pair('隋唐','隋唐'),yuan:pair('元代','元代'),mingqing:pair('明清','明清'),modern:pair('近现代','近現代')};
const relationLabels={direct:pair('中日直接联系','日中の直接的関係'),context:pair('历史背景','歴史的背景'),memory:pair('纪念与传本','記念・伝本'),conflict:pair('战争与冲突','戦争・対立')};
const kindLabels={ruin:pair('遗址','遺跡'),building:pair('建筑','建築'),museum:pair('馆藏与展陈','所蔵・展示'),document:pair('文件节点','文書の接点'),institution:pair('合作机构','協力機関')};
const zoneLabels={northwest:pair('西北','北西'),north:pair('北','北'),northeast:pair('东北','北東'),west:pair('西','西'),center:pair('中心','中心'),east:pair('东','東'),southwest:pair('西南','南西'),south:pair('南','南'),southeast:pair('东南','南東'),outer:pair('城市外围／区域延伸','郊外・地域への接続')};
const sourceKinds={primary:pair('正式文本','公式本文'),object:pair('馆藏材料解说','所蔵資料解説'),archive:pair('档案选编','档案選編'),heritage:pair('遗产资料','遺産資料'),institution:pair('机构介绍','機関紹介'),reference:pair('专业辞典','専門辞典'),'research-report':pair('研究报道','研究紹介'),design:pair('教学设计参考','教育設計参考')};
let filters={city:'all',era:'all',relation:'all',placeQ:'',timeQ:'',timeRelation:'all',period:'all',sourceKind:'all',peopleQ:''};
let toastTimer;
let selectedNoteKey=null;
let searchQuery="";
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));persistenceOK=true;return true;}catch{persistenceOK=false;toast(t('当前浏览器无法保存，请导出备份。','保存できません。バックアップを書き出してください。'));return false;}}
function toast(message){const el=document.getElementById('toast');el.textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.textContent='';},3500);}
function route(){
 const hash=location.hash.slice(1)||'home';
 try{return decodeURIComponent(hash).split('/');}catch{return [hash];}
}
function go(hash){if(location.hash===`#${hash}`){render();window.scrollTo(0,0);}else location.hash=hash;}
const button=(label,action,extra='',cls='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const link=(label,hash,cls='btn')=>`<a class="${cls}" href="#${esc(hash)}">${label}</a>`;
const external=(url,label,cls='')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const badge=(label,cls='')=>`<span class="tag ${cls}">${bi(label)}</span>`;
function siteConnections(kind,id){
 const matches=Object.entries(DATA.siteLinks).filter(([,entry])=>entry[kind]===id);
 if(!matches.length)return '';
 return `<div class="actions">${matches.map(([eventId,event])=>{
  const {track}=event;
  return `<a class="btn small" href="/#timeline/${esc(track)}/${esc(eventId)}">${bi(event.title)} ↗</a>`;
 }).join('')}</div>`;
}
function refs(ids){return `<div class="refline" aria-label="${t('本段参考资料','この節の参考資料')}">${[...new Set(ids||[])].map(id=>{const s=get('sources',id);return s?link(esc(s.org)+' · '+esc(s.id),'source/'+s.id,''):'';}).join('')}</div>`;}
function sourceItem(s, detail=false){return `<article class="sourceitem" id="source-${esc(s.id)}"><div>${badge(sourceKinds[s.kind]||pair('资料','資料'))} <span class="small">${esc(s.id)} · ${esc(s.org)}</span></div><h3>${detail?external(s.url,esc(s.title)):link(esc(s.title),'source/'+s.id,'')}</h3><p>${bi(s.use)}</p><div class="smallmeta">${B('条目核对','項目確認')} ${esc(s.checked)} · ${B('引用前请回到原件或正式文本','引用前に原件・公式本文を確認')}</div></article>`;}
function symbol(kind='temple',city='xian'){
 const c=city==='beijing'?['#ad5841','#d6a46a','#f6e9d9']:['#38695a','#8aa77d','#e6eddc'];
 if(kind==='object')return `<svg viewBox="0 0 500 210" aria-hidden="true"><circle cx="250" cy="105" r="86" fill="${c[2]}"/><rect x="153" y="42" width="194" height="137" rx="6" fill="#fffcf0" stroke="${c[0]}" stroke-width="2"/><path d="M165 57h168M180 77h140M180 96h105M180 115h140M180 134h95M180 153h140" stroke="${c[1]}" stroke-width="6"/><rect x="305" y="127" width="24" height="24" fill="${c[0]}" opacity=".6"/></svg>`;
 if(kind==='wall')return `<svg viewBox="0 0 500 210" aria-hidden="true"><circle cx="250" cy="90" r="75" fill="${c[2]}"/><path d="M40 174h420V104h-25V86h-25v18h-32V86h-25v18H147V86h-25v18H90V86H65v18H40z" fill="${c[1]}"/><path d="M223 174v-47a27 27 0 0 1 54 0v47" fill="${c[0]}"/><path d="M25 177h450M154 82h193M179 57h143" stroke="${c[0]}" stroke-width="6"/><path d="M151 80l48-29h100l48 29M179 55l45-30h52l46 30" fill="${c[0]}"/><path d="M157 118h45m97 0h45M55 143h140m110 0h140" stroke="#fff7e2" stroke-width="2" opacity=".5"/></svg>`;
 if(kind==='pagoda')return `<svg viewBox="0 0 500 210" aria-hidden="true"><circle cx="250" cy="100" r="84" fill="${c[2]}"/>${[0,1,2,3,4].map(i=>{const w=130-i*18,y=170-i*28;return `<rect x="${250-w/2}" y="${y-25}" width="${w}" height="25" fill="${c[1]}"/><path d="M${241-w/2} ${y-25}l${w/2+9} -13 ${w/2+9} 13z" fill="${c[0]}"/><rect x="245" y="${y-20}" width="10" height="16" fill="${c[0]}"/>`;}).join('')}<path d="M100 180h300" stroke="${c[0]}" stroke-width="2"/></svg>`;
 return `<svg viewBox="0 0 500 210" aria-hidden="true"><circle cx="320" cy="76" r="43" fill="${c[2]}"/><path d="M40 172Q90 125 145 158T270 151T460 170" fill="none" stroke="${c[1]}" opacity=".35" stroke-width="2"/><rect x="130" y="104" width="240" height="69" fill="${c[1]}"/><path d="M95 108q25-4 48-37h214q22 33 48 37zM159 65q20-4 38-28h106q18 24 38 28z" fill="${c[0]}"/><path d="M125 176h250M152 151h196" stroke="${c[0]}" stroke-width="5"/><rect x="230" y="115" width="40" height="59" fill="${c[0]}"/><path d="M160 114v55m40-55v55m100-55v55m40-55v55" stroke="#fff3da" stroke-width="4"/><circle cx="93" cy="139" r="20" fill="${c[1]}"/><path d="M93 152v23" stroke="${c[0]}" stroke-width="4"/></svg>`;
}
function homeArt(){return `<svg viewBox="0 0 560 330" role="img" aria-label="${t('城市、人物和史料的关联意象','都市・人物・史料を結ぶイメージ')}"><path d="M64 241C130 140 260 300 382 175S490 134 501 66" fill="none" stroke="#98b39a" stroke-width="2" stroke-dasharray="5 7"/><circle cx="150" cy="126" r="86" fill="#f9f5e8"/><circle cx="405" cy="200" r="89" fill="#efcfbb"/><g transform="translate(-23,29) scale(.69)">${symbol('temple').replace(/<svg[^>]*>|<\/svg>/g,'')}</g><g transform="translate(224,104) scale(.7)">${symbol('wall','beijing').replace(/<svg[^>]*>|<\/svg>/g,'')}</g><rect x="255" y="48" width="82" height="112" rx="7" fill="#fffaf0" stroke="#b8c3aa" transform="rotate(8 295 104)"/><path d="M274 70h45M274 87h45M274 104h32M274 121h45" stroke="#b9aa80" stroke-width="4" transform="rotate(8 295 104)"/><circle cx="103" cy="250" r="22" fill="#38695a"/><text x="103" y="257" fill="white" text-anchor="middle" font-size="18">文</text><circle cx="468" cy="65" r="18" fill="#ad5841"/><text x="468" y="71" fill="white" text-anchor="middle" font-size="16">史</text></svg>`;}
function placeSymbol(p){return symbol(['beilin','nwu','shaanxi','guozijian','hall','memorial'].includes(p.id)?'object':['wall','daming','weiyang','dadu','lugou'].includes(p.id)?'wall':['dayan','xiaoyan','xingjiao'].includes(p.id)?'pagoda':'temple',p.city);}
function photoBlock(p){const im=get('images',p.image);return `<figure class="media"><div class="visual">${im&&state.photos?`<img data-photo="${esc(im.id)}" src="${esc(im.url)}" alt="${esc(plain(im.title))}" loading="lazy" referrerpolicy="no-referrer">`:placeSymbol(p)}</div><figcaption>${im&&state.photos?`${bi(im.title)} · ${esc(im.date)} · ${esc(im.creator)} · ${external(im.licenseUrl,esc(im.license))} ${external(im.page,t('图源','出典'))}`:B('学习意象图，不是该建筑的测绘或历史复原。','学習用イメージ。実測図・歴史復元図ではない。')}${im&&!state.photos?`<div class="actions">${button(B('查看实景照片','現地写真を見る'),'photos','', 'small')}${external(im.page,t('查看原图与许可','原画像と許諾'),'btn small')}</div>`:''}</figcaption></figure>`;}
function placeCard(p){return `<article class="card placecard ${esc(p.city)}"><a class="cover" style="display:block" href="#place/${esc(p.id)}" aria-label="${esc(plain(p.title))}">${placeSymbol(p)}</a><div class="cardbody"><div>${badge(relationLabels[p.relation],p.relation)}${badge(eraLabels[p.era])}</div><h3><a href="#place/${esc(p.id)}">${bi(p.title)}</a></h3><p>${bi(p.summary)}</p><div class="cardbottom">${link(B('进入阅读','読む'),'place/'+p.id,'btn small')}${button(state.compare.includes(p.id)?t('✓ 已选比较','✓ 比較中'):t('＋ 比较','＋ 比較'),'compare',`data-id="${esc(p.id)}"`,'small')}</div></div></article>`;}
function pathCard(r,i=0){const n=r.steps.filter(id=>state.completed.includes('place:'+id)).length;return `<a class="card cardlink pathcard" href="#route/${esc(r.id)}"><span class="pathnum">${String(i+1).padStart(2,'0')}</span><div><h3>${bi(r.title)}</h3><p class="muted">${bi(r.description)}</p><div class="steps">${r.steps.map(id=>`<span class="step ${state.completed.includes('place:'+id)?'done':''}"></span>`).join('')}</div><div class="smallmeta">${n} / ${r.steps.length} ${B('地点已读 · 阅读顺序，非游览线路','読了・読書の順序であり観光ルートではない')}</div></div></a>`;}
function eventCard(e){return `<a class="event-row" href="#event/${esc(e.id)}"><div class="date">${esc(dateLabel(e.date))}</div><div>${badge(cityname(e.city))}${badge(relationLabels[e.relation],e.relation)}<h3>${bi(e.title)}</h3><p>${bi(e.summary)}</p></div></a>`;}
function studyCard(s,i=0){return `<a class="card cardlink" href="#study/${esc(s.id)}"><div class="eyebrow">${String(i+1).padStart(2,'0')} / ${t('深入探索','深く学ぶ')}</div><h3>${bi(s.title)}</h3><p>${bi(s.lead)}</p><div class="smallmeta">${s.sections.length} ${B('节 · 史料与方法','節・史料と方法')} ↗</div></a>`;}
function head(){const [r,id]=route();const nav=[['home',t('入口','入口')],['city/xian',t('西安','西安')],['city/beijing',t('北京','北京')],['timeline',t('时间线','年表')],['people',t('人物','人物')],['sources',t('史料室','史料室')],['notebook',t('摘记','ノート')]];return `<div class="top"><a class="brand" href="#home"><span class="seal">渡</span><span><strong>${t('跨海的历史','海をわたる歴史')}</strong><small>HISTORY ACROSS THE SEA</small></span></a><nav class="nav" aria-label="${t('主要导航','メインナビゲーション')}">${nav.map(([h,l])=>`<a href="#${h}" class="${r==='city'?h===r+'/'+id?'active':'':h===r?'active':''}" ${h===r||h===r+'/'+id?'aria-current="page"':''}>${l}</a>`).join('')}<a href="#search" aria-label="${t('城市专题搜索','都市特集を検索')}">⌕</a></nav><div class="language" aria-label="${t('阅读语言','言語')}">${[['zh','中'],['ja','日本語'],['dual','中 / 日']].map(([v,l])=>`<button data-action="lang" data-value="${v}" class="${state.lang===v?'active':''}" aria-pressed="${state.lang===v}">${l}</button>`).join('')}</div></div><div class="statusbar"><span class="statusdot"></span>${t('城市探索','都市をめぐる')}<span class="atlas-site-links"><a href="/">${t('返回主站','メインサイトへ')}</a>${link(t('关于专题','特集について'),'about','')}</span></div>`;}
function footer(){return `<div>${t('跨海的历史 · 北京 × 西安','海をわたる歴史・北京 × 西安')}<br>${t('机构资料 + 编辑解读；不是专家审定教材。','機関資料＋編集解説。専門家査定済み教材ではありません。')}</div><div>${link(t('图源、范围与修订说明','画像・範囲・訂正の説明'),'about','')} · ${link(t('地点比较','地点を比較'),'compare','')}<br>${t('学习记录保存在当前浏览器','学習記録はこのブラウザーに保存されます')}</div>`;}
function home(){const featured=['x-k804','x-k805','x-enchin','b-1937','b-1972','b-1978s'].map(id=>get('events',id));return `<section class="hero"><div><div class="eyebrow">CHAPTER 06 / ${t('从一座城市开始','都市から始める')}</div><h1>${t('沿着古都，<br>读懂<span class="accent">跨海的历史。</span>','古都をたどり、<br><span class="accent">海を越える歴史へ。</span>')}</h1><p>${B('地点是入口，人物、事件与史料让历史连接起来。','場所を入口に、人・出来事・史料をつないで学ぶ。')}</p><div class="actions">${link(B('探索西安 →','西安へ →'),'city/xian','btn primary')}${link(B('打开北京专题','北京を開く'),'city/beijing','btn')}</div><div class="smallmeta">${DATA.places.length} ${B('处地点','地点')} · ${DATA.events.length} ${B('个年代节点','年表項目')} · ${DATA.studies.length} ${B('篇深读','深読記事')}</div></div><div class="hero-art">${homeArt()}<span class="art-label">${t('城市与文书 · 意象图','都市と文書・イメージ')}</span></div></section>
<section class="section"><div class="sectionhead"><h2>${B('今天，从哪里开始？','今日は、どこから？')}</h2>${link(B('查看全部学习路径 ↗','学習パスをすべて見る ↗'),'routes','')}</div><div class="grid2"><a class="card cardlink city-entry xian" href="#city/xian"><div class="copy"><span class="number">01 · CHANG’AN / XI’AN</span><h2>${B('西安','西安')}</h2><p>${B('都城 · 寺院 · 知识的旅程','都城・寺院・知識の旅')}</p><span class="arrow">→</span></div><div class="cityart">${symbol('pagoda')}</div></a><a class="card cardlink city-entry beijing" href="#city/beijing"><div class="copy"><span class="number">02 · BEIJING</span><h2>${B('北京','北京')}</h2><p>${B('帝都 · 近代 · 和平与合作','帝都・近代・平和と協力')}</p><span class="arrow">→</span></div><div class="cityart">${symbol('wall','beijing')}</div></a></div></section>
<section class="section quick" aria-label="${t('探索方式','探索方法')}">${[['timeline','◷','blue','年代对照','年代を比べる','先后关系，先看清','前後関係を確かめる'],['people','⌘','purple','人物网络','人物ネットワーク','关系有出处','関係には根拠を'],['sources','▤','gold','史料阅览','史料を読む','看原文，也看边界','本文と限界を見る'],['compare','⇄','','地点比较','場所を比べる','相似不等于相同','類似と同一を分ける']].map(([h,ic,cl,z,j,sz,sj])=>`<a class="${cl}" href="#${h}"><span class="icon">${ic}</span><div><strong>${B(z,j)}</strong><small>${B(sz,sj)}</small></div></a>`).join('')}</section>
<section class="section card"><div class="sectionhead"><div><div class="eyebrow">TIME CONNECTIONS</div><h2>${B('跨过年代，看见联系','年代を越えて、つながりを見る')}</h2></div>${link(B('完整城市年表 →','都市年表へ →'),'timeline','')}</div><div class="compactline">${featured.map(e=>`<a class="mini-event" href="#event/${e.id}"><span class="yr">${esc(e.year)}</span><strong>${bi(e.title)}</strong></a>`).join('')}</div><div class="smallmeta">${B('精选节点按顺序排列，不按时间跨度缩放。','選択項目を年代順に表示。時間幅に比例した図ではない。')}</div></section>
<section class="section"><div class="sectionhead"><h2>${B('带着一个问题，深入一点','一つの問いから、もう一歩')}</h2>${link(B('全部深读 →','全記事 →'),'studies','')}</div><div class="grid3 studycards">${DATA.studies.slice(0,3).map(studyCard).join('')}</div></section><section class="section"><div class="grid2">${DATA.routes.filter(r=>['x-exchange','b-peace'].includes(r.id)).map(pathCard).join('')}</div></section>`;}
function selector(id,label,entries,value){return `<label>${bi(label)}<select id="${id}" data-filter="${id}">${entries.map(([k,v])=>`<option value="${esc(k)}" ${k===value?'selected':''}>${esc(plain(v))}</option>`).join('')}</select></label>`;}
function filterPlaces(city){return DATA.places.filter(p=>p.city===city&&(filters.era==='all'||p.era===filters.era)&&(filters.relation==='all'||p.relation===filters.relation)&&JSON.stringify(p).toLowerCase().includes(filters.placeQ.toLowerCase()));}
function atlas(city){const all=DATA.places.filter(p=>p.city===city);return `<aside class="card atlas"><div class="eyebrow">SPATIAL READING</div><h3>${B('按方位找地点','方位から場所を探す')}</h3><div class="mapgrid">${Object.keys(zoneLabels).filter(k=>k!=='outer').map(zone=>`<div class="zone"><small>${bi(zoneLabels[zone])}</small>${all.filter(p=>p.zone===zone).map(p=>`<a class="${p.relation}" href="#place/${p.id}">${bi(p.title)}</a>`).join('')}</div>`).join('')}</div>${all.some(p=>p.zone==='outer')?`<div class="outer"><div class="hint">${bi(zoneLabels.outer)}</div>${all.filter(p=>p.zone==='outer').map(p=>link(bi(p.title),'place/'+p.id,'')).join('')}</div>`:''}<p class="hint" style="margin-top:14px">${bi(DATA.notes.map)}</p><div class="refline">${external(city==='xian'?get('sources','silkmaps').url:get('sources','axis').url,t('官方遗产定位入口','公式遺産位置資料'))}</div></aside>`;}
function city(id){if(!['xian','beijing'].includes(id))return notfound();const isX=id==='xian';return `<div class="crumb">${link(t('入口','入口'),'home','')} / ${bi(cityname(id))}</div><div class="titlebar"><div><div class="eyebrow">${isX?'CHANG’AN / XI’AN':'BEIJING'} · CITY ATLAS</div><h1>${isX?B('西安：古都里的多重时间','西安：古都に重なる時間'):B('北京：城市、国家与跨海关系','北京：都市、国家、海を越える関係')}</h1><p>${isX?B('从半坡到明城墙，从青龙寺到求法目录。','半坡から明代城壁へ、青龍寺から求法目録へ。'):B('从中轴线的空间秩序，走向近代事件与现代合作。','中軸線の空間秩序から、近代の出来事と現代の協力へ。')}</p></div>${link(B('按年代阅读 →','年代順に読む →'),'timeline/'+id,'btn')}</div><div class="toolbar">${selector('era',pair('时代','時代'),[['all',pair('全部时代','すべて')],...Object.entries(eraLabels)],filters.era)}${selector('relation',pair('与交流的关系','交流との関係'),[['all',pair('全部类别','すべて')],...Object.entries(relationLabels)],filters.relation)}<input id="place-search" type="search" placeholder="${t('检索地点、人物、关键词','場所・人物・キーワードを検索')}" aria-label="${t('筛选地点','地点を絞る')}" value="${esc(filters.placeQ)}"></div><div class="twocol">${atlas(id)}<div><div id="place-count" class="hint" style="margin-bottom:14px"></div><div id="place-results" class="placegrid"></div></div></div><section class="section"><div class="sectionhead"><h2>${B('给这座城市，一条学习路径','この都市を学ぶパス')}</h2></div><div class="grid2">${DATA.routes.filter(r=>r.city===id).map(pathCard).join('')}</div></section>`;}
function updatePlaces(id){const ps=filterPlaces(id);document.getElementById('place-count').innerHTML=`${ps.length} ${B('处地点 · 图标为分类意象，不是实景复原','地点・アイコンは分類イメージであり実景復元ではない')}`;document.getElementById('place-results').innerHTML=ps.length?ps.map(placeCard).join(''):`<div class="empty">${B('没有匹配地点，请调整筛选。','該当なし。条件を変更してください。')}</div>`;}
function articleOutline(items){return `<aside class="outline"><div class="hint">${B('阅读目录','目次')}</div>${items.map(([id,label])=>`<a href="#${esc(location.hash.slice(1))}" data-scroll="${id}">${label}</a>`).join('')}</aside>`;}
function actionRow(type,id){const key=type+':'+id;return `<div class="actions">${button(state.bookmarks.includes(key)?B('★ 已收藏','★ 保存済み'):B('☆ 收藏','☆ 保存'),'bookmark',`data-type="${type}" data-id="${id}"`,state.bookmarks.includes(key)?'saved':'')}${button(B('写一条摘记','ノートを書く'),'note',`data-type="${type}" data-id="${id}"`)}${type==='place'?button(state.compare.includes(id)?B('✓ 已选比较','✓ 比較中'):B('⇄ 加入比较','⇄ 比較へ'),'compare',`data-id="${id}"`):''}${button(B('打印／另存为PDF','印刷・PDF保存'),'print','', 'small')}</div>`;}
function completion(type,id){return `<div class="reading-footer"><label class="readcheck"><input type="checkbox" data-complete="${type}:${id}" ${state.completed.includes(type+':'+id)?'checked':''}>${B('我已读完，并能说出至少一条证据与一个限制。','読み終え、少なくとも一つの証拠と限界を説明できる。')}</label><div class="smallmeta">${B('这是自我记录，不代表专业水平认证。仅保存在当前浏览器。','自己記録であり専門能力の認定ではない。このブラウザーにのみ保存。')}</div></div>`;}
function place(id){const p=get('places',id);if(!p)return notfound();const es=DATA.events.filter(e=>e.places.includes(id));const ss=DATA.studies.filter(s=>s.places.includes(id));return `<div class="crumb">${link(plain(cityname(p.city)),'city/'+p.city,'')} / ${bi(p.title)}</div><div class="article-layout">${articleOutline([['context',t('01 历史情境','01 歴史の文脈')],['visual',t('02 图解定位','02 図解')],['method',t('03 怎样读材料','03 史料の読み方')],['limits',t('04 解释的边界','04 解釈の限界')],['links',t('05 人物与年代','05 人物と年代')],['references',t('06 参考依据','06 参考資料')]])}<article class="article"><div class="tagrow">${badge(eraLabels[p.era])}${badge(kindLabels[p.kind])}${badge(relationLabels[p.relation],p.relation)}</div><h1>${bi(p.title)}</h1><p class="lead">${bi(p.summary)}</p>${actionRow('place',id)}${photoBlock(p)}<section class="article-section" id="context"><h2><span class="sectionno">01</span>${B('历史情境','歴史の文脈')}</h2><p class="bodytext">${bi(p.body)}</p>${refs(p.refs)}</section><section class="article-section" id="visual">${p.id==='qinglong'?diagram('network'):p.id==='hall'?diagram('diplomacy'):p.id==='hospital'?diagram('cooperation'):['beilin','guozijian','nwu','shaanxi','xishi'].includes(id)?diagram('object'):['lugou','memorial','red'].includes(id)?diagram('evidence'):diagram('layers')}</section><section class="article-section" id="method"><h2><span class="sectionno">03</span>${B('怎样读材料','史料をどう読むか')}</h2><p class="bodytext">${bi(p.method)}</p>${refs(p.refs)}</section><section id="limits" class="box warning article-section"><h3>${B('解释的边界','解釈の限界')}</h3><p>${bi(p.limit)}</p></section><div class="box task"><h3>${B('留下自己的判断','自分の判断を残す')}</h3><p>${bi(p.question)}</p>${button(B('把问题带入摘记 →','問いをノートへ →'),'note',`data-type="place" data-id="${id}"`,'small')}</div><section class="article-section" id="links"><h2><span class="sectionno">05</span>${B('人物与年代，继续连接','人物と年代から、先へ')}</h2><div class="actions">${p.people.map(pid=>link(bi(get('people',pid).title),'person/'+pid,'btn small')).join('')}</div>${siteConnections('place',id)}<div class="event-list" style="margin-top:16px">${es.length?es.map(eventCard).join(''):`<div class="hint">${B('此地点暂无独立年代节点；不为填满时间线虚构事件。','独立した年代項目はまだない。年表を埋めるために出来事を作らない。')}</div>`}</div>${ss.length?`<div class="grid2 studycards section">${ss.map(studyCard).join('')}</div>`:''}</section><section class="article-section" id="references"><h2>${B('参考依据与材料用途','根拠と資料の用途')}</h2>${p.refs.map(r=>sourceItem(get('sources',r))).join('')}</section>${completion('place',id)}</article></div>`;}
const diagramData={
 layers:{title:pair('同一座城市，不同的时间层','同じ都市、異なる時間層'),note:pair('分类示意，非遗址原貌或按比例地图。点击每一层，改变观察问题。','分類模式図。遺跡復元図や縮尺地図ではない。層を選び、観察の問いを変える。'),refs:['silkmaps','axis','wall'],nodes:[['古代 / 古代','遗址与文献','遺構と文献','先确认对象属于哪个时代，再看遗址、文字和年代是否相互支持。','対象の時代を定め、遺構・文献・年代が相互に支えるか確認する。'],['后世 / 後世','重修与传本','修復と伝本','重修、补刻和抄写会留下新的材料层。它们不是无价值，但不等于原初状态。','修復・補刻・書写は新たな層を残す。重要だが原初状態とは同じではない。'],['今天 / 現在','保护与展示','保存と展示','现在看见的照片、纪念堂和展签，首先记录现代保护与解释活动。','今見る写真・記念堂・展示解説は、まず現代の保存と解釈を記録する。']]},
 network:{title:pair('青龙寺求法：分开人物，连接证据','青龍寺での求法：人物を分け、証拠を結ぶ'),note:pair('并列比较，不是三人同时在场，也不表示三人互为师承。','並列比較。同席や三人相互の師承を意味しない。'),refs:['kukai','ennin','enchin'],nodes:[['805','空海 → 惠果','空海 → 恵果','人物年表与寺院资料支持受法关系。把取得经论、图像、法具和仪式学习分别研究。','年譜と寺院資料が受法を支える。経論・図像・法具・儀礼学習を個別に調べる。'],['838–847','圆仁 · 求法旅程','円仁・求法の旅','目录与日记提供不同线索。扬州的指导、僧人所属寺院和1095年传本不要合并。','目録と日記は異なる手掛かり。揚州での指導、僧の所属寺院、1095年写本を分ける。'],['855','圆珍 → 法全','円珍 → 法全','目录提供取得物和认证信息；同名寺院在不同年代承载不同人物关系。','目録は取得物と証明の情報を示す。同じ寺院でも時代により人物関係は異なる。']]},
 diplomacy:{title:pair('三个日期，三种行为','三つの日付、三つの行為'),note:pair('顺序图，不按年份间隔缩放。','順序図。年の間隔に比例していない。'),refs:['jointzh','jointja','treaty','normalization'],nodes:[['1972.09.29','发表联合声明','共同声明発表','比较两国官方文本的主体、动词与对象。本页解释不替代正式原文。','両国の公式本文の主体・動詞・対象を比較する。本解説は正文に代わらない。'],['1978.08.12','在北京签署条约','北京で条約署名','记录签署地点、日期与文书性质，不把签署日当作生效日。','署名地・日付・文書の性格を記録し、署名日と発効日を分ける。'],['1978.10.23','条约生效','条約発効','法律状态变化的时间节点。并不代表所有社会关系在同日完全改变。','法的状態の変化。社会関係すべてが同日に変わることを意味しない。']]},
 evidence:{title:pair('事件 → 材料 → 展示：不是同一层','出来事 → 史料 → 展示：同じ層ではない'),note:pair('史料阅读流程。箭头表示研究步骤，不表示事件之间的因果。','史料読解の手順。矢印は研究手順であり出来事の因果ではない。'),refs:['lugou','surrender','mit'],nodes:[['01','事件发生','出来事','先建立日期、地点和参与者；不把后来的结果当作当时每个人都知道的信息。','日付・場所・関係者を確認し、後の結果を当時の全員が知っていた情報としない。'],['02','材料形成','資料成立','记录作者、目的、形成时间、所见范围，以及原件还是复制件。','作成者・目的・成立時点・認識範囲、原件か複製かを記す。'],['03','今天的展示','現在の展示','观察选择、编排与注释；区分历史照片与展示现场的照片。','選択・配列・注釈を観察し、歴史写真と展示風景の写真を分ける。']]},
 object:{title:pair('一件材料的三张“身份证”','資料の三つの基本情報'),note:pair('对原石、拓本、古籍、器物均可使用的观察框架。','石碑・拓本・古籍・器物に使える観察枠組み。'),refs:['beilin','enchin','ino'],nodes:[['物 / 物','原件与年代','原件と年代','是什么物件？怎样断代？哪部分文字或图像能够直接观察？','何の物件か。どう年代を決めたか。何を直接観察できるか。'],['传 / 伝','复制与流通','複製と流通','是原件、拓本、抄本还是摄影？谁在何时制作或保存？','原件・拓本・写本・写真のどれか。誰がいつ制作・保存したか。'],['释 / 釈','解释与用途','解釈と用途','馆方解说、学术解释与本站导读各在哪一层？哪些结论还缺证据？','所蔵解説・研究解釈・本站ガイドを分け、証拠の不足を確認する。']]},
 chain:{title:pair('“影响”不是一个箭头','影響は一本の矢印ではない'),note:pair('分析框架，不是所有文化传播都经过同样的线性过程。','分析枠組み。すべての伝播が同じ直線的過程を通るわけではない。'),refs:['murals','enchin','passport'],nodes:[['观察 / 観察','相似的特征','似た特徴','描述可见特征。相似可以提出问题，却不单独证明传播方向。','見える特徴を記す。類似は問いになるが、伝播方向を単独では証明しない。'],['移动 / 移動','接触与流通','接触と流通','查目录、通行文书、收藏印和出土情境，追踪具体移动。','目録・通行文書・蔵書印・出土状況で具体的移動を追う。'],['使用 / 利用','选择与接受','選択と受容','寻找抄写、注释、教学、改造等接收端材料，解释当地的变化。','書写・注釈・教育・改変など受け手の資料から変化を説明する。']]},
 cooperation:{title:pair('合作怎样进入日常','協力はどう日常へ入るか'),note:pair('项目研究框架，不宣称已完成独立成效评价。','事業研究の枠組み。独立した成果評価を実施したものではない。'),refs:['hospital','aid'],nodes:[['01','协议与投入','合意と投入','确认合作方、资金或技术范围；项目名称本身不是成果。','協力者・資金・技術範囲を確認する。名称そのものは成果ではない。'],['02','建设与培训','建設と研修','将竣工、设备、培训与开院分开记录。工程完成不等于长期运营成功。','竣工・設備・研修・開院を分ける。完成と長期運営の成功は別。'],['03','长期运营','継続的運営','独立研究需要运营与评价资料；不收集患者信息，不安排观光闯入。','独立研究には運営・評価資料が必要。患者情報収集や観光立入りを行わない。']]}}
function diagram(kind){const d=diagramData[kind]||diagramData.evidence;return `<div class="diagram" data-diagram="${kind}"><div class="eyebrow">LEARNING DIAGRAM</div><h3>${bi(d.title)}</h3><div class="diagramnodes ${kind==='network'?'network-nodes':'sequence-nodes'}">${d.nodes.map((n,i)=>`<button class="dnode ${i===0?'active':''}" data-action="diagram" data-kind="${kind}" data-index="${i}" aria-pressed="${i===0}"><b>${esc(n[0])}</b><small>${B(n[1],n[2])}</small></button>`).join('')}</div><div class="dreadout" aria-live="polite">${B(d.nodes[0][3],d.nodes[0][4])}</div><div class="diagram-note">${bi(d.note)}</div>${refs(d.refs)}</div>`;}
function timeline(city){const initialCity=['xian','beijing'].includes(city)?city:filters.city;filters.city=initialCity;return `<div class="titlebar"><div><div class="eyebrow">CITIES IN TIME</div><h1>${B('城市历史时间线','都市の歴史年表')}</h1><p>${B('事件、物件与现代发现分开标明；跨城延伸不会被当作本地发生。','出来事・資料・現代の発見を区別。都市外の関連事項は現地の出来事と同一視しない。')}</p></div></div><div class="toolbar">${selector('city',pair('城市','都市'),[['all',pair('两座城市','両都市')],['xian',cityname('xian')],['beijing',cityname('beijing')]],filters.city)}${selector('period',pair('时段','時期'),[['all',pair('全部时段','すべて')],['ancient',pair('先秦至唐','先秦～唐')],['medieval',pair('宋元明清','宋元明清')],['modern',pair('近现代','近現代')]],filters.period)}${selector('timeRelation',pair('关系','関係'),[['all',pair('全部类别','すべて')],...Object.entries(relationLabels)],filters.timeRelation)}<input id="timeline-search" type="search" placeholder="${t('年份、人物、事件','年代・人物・出来事')}" aria-label="${t('搜索时间线','年表検索')}" value="${esc(filters.timeQ)}"></div><div id="timeline-count" class="hint"></div><div id="timeline-results" style="margin-top:17px"></div>`;}
function updateTimeline(){const es=DATA.events.filter(e=>(filters.city==='all'||e.city===filters.city)&&(filters.timeRelation==='all'||e.relation===filters.timeRelation)&&(filters.period==='all'||filters.period==='ancient'&&e.year<1000||filters.period==='medieval'&&e.year>=1000&&e.year<1840||filters.period==='modern'&&e.year>=1840)&&JSON.stringify(e).toLowerCase().includes(filters.timeQ.toLowerCase()));document.getElementById('timeline-count').innerHTML=`${es.length} ${B('个节点 · 以精选事件构建城市学习线索，不是完整通史。','項目・都市学習のための選択であり完全な通史ではない。')}`;document.getElementById('timeline-results').innerHTML=es.length?`<div class="timeline-strip" tabindex="0" aria-label="${t('横向编年带，可滚动','横スクロール年表')}"><div class="timeline-inner">${es.map(e=>`<a class="timecell ${e.city}" href="#event/${e.id}"><b>${esc(dateLabel(e.date))}</b><span>${bi(e.title)}</span></a>`).join('')}</div></div><div class="hint" style="margin-bottom:18px">${B('卡片等距按年代排序，不按实际时间跨度缩放；准确日期与范围见下方条目。','カードは年代順に等間隔配置。時間幅に比例しない。正確な日付と範囲は下記。')}</div><div class="event-list">${es.map(eventCard).join('')}</div>`:`<div class="empty">${B('没有匹配事件。','該当する出来事がありません。')}</div>`;}
function eventPage(id){const e=get('events',id);if(!e)return notfound();return `<div class="crumb">${link(t('城市年表','都市年表'),'timeline/'+e.city,'')} / ${esc(dateLabel(e.date))}</div><div class="article-layout">${articleOutline([['context',t('事件与相关地点','出来事と関連地点')],['references',t('来源','出典')]])}<article class="article"><div class="tagrow">${badge(cityname(e.city))}${badge(relationLabels[e.relation],e.relation)}${badge(pair('日期精度：'+({year:'年',range:'范围',day:'日',century:'世纪',decade:'年代'}[e.precision]||e.precision),'日付精度：'+({year:'年',range:'範囲',day:'日',century:'世紀',decade:'年代'}[e.precision]||e.precision)))}</div><div class="eyebrow">${esc(dateLabel(e.date))}</div><h1>${bi(e.title)}</h1><p class="lead">${bi(e.summary)}</p>${actionRow('event',id)}<section class="article-section" id="context"><h2>${B('通过地点，进入完整阅读','場所から詳しく読む')}</h2><div class="placegrid">${e.places.map(pid=>placeCard(get('places',pid))).join('')}</div><div class="actions">${e.people.map(pid=>link(bi(get('people',pid).title),'person/'+pid,'btn small')).join('')}</div>${siteConnections('event',id)}</section><section class="article-section" id="references"><h2>${B('资料与用途','資料と用途')}</h2>${e.refs.map(r=>sourceItem(get('sources',r))).join('')}</section><div class="box task"><h3>${B('将日期写准确','日付を正確に記す')}</h3><p>${B('这是事件发生、文物制作、发现还是纪念的日期？发生地、保存地与关联城市是否相同？','出来事・制作・発見・記念のどの日付か。発生地・所蔵地・関連都市は同じか。')}</p></div>${completion('event',id)}</article></div>`;}
function people(){return `<div class="titlebar"><div><div class="eyebrow">PEOPLE & EVIDENCE</div><h1>${B('人物，不是孤立的名字','人物を、名前だけで終わらせない')}</h1><p>${B('以与城市直接相关的经历为中心，不将未核实部分拼成完整传记。','都市と直接関わる経験を中心に、未確認部分で完全な伝記を作らない。')}</p></div></div><div class="grid4">${DATA.people.map(p=>`<a href="#person/${p.id}" class="card cardlink peoplecard"><span class="avatar">${esc(p.title.zh.slice(0,1))}</span><h3>${bi(p.title)}</h3><div class="years">${esc(p.years)}</div><p>${bi(p.summary)}</p><div class="smallmeta">${B('人物档案 →','人物資料へ →')}</div></a>`).join('')}</div><section class="section card"><h2>${B('有依据的关系网络','根拠のある関係ネットワーク')}</h2><p class="hint" style="margin-top:8px">${B('每条边有独立标签和出处。关联不一概等于师生，也不等于同时见面。','線ごとに関係と出典を表示。すべてが師弟や同時の面会を意味するわけではない。')}</p>${relationGraph(DATA.relations)}</section>`;}
function relationGraph(rs){return `<div class="relation-list">${rs.map(r=>{const a=get('people',r.a)||get('places',r.a),b=get('people',r.b)||get('places',r.b);return `<div><div class="relation-edge">${link(bi(a.title),(get('people',r.a)?'person/':'place/')+r.a,'')}<span>${bi(r.label)}</span>${link(bi(b.title),(get('people',r.b)?'person/':'place/')+r.b,'')}</div>${refs(r.refs)}</div>`;}).join('')}</div>`;}
function personPage(id){const p=get('people',id);if(!p)return notfound();const rs=DATA.relations.filter(r=>r.a===id||r.b===id);const ev=DATA.events.filter(e=>e.people.includes(id));return `<div class="crumb">${link(t('人物网络','人物ネットワーク'),'people','')} / ${bi(p.title)}</div><article class="article" style="margin:auto"><div class="eyebrow">${esc(p.years)} · ${t('专题相关年段，不是生卒年','特集の関連年代。生没年ではない')}</div><h1>${bi(p.title)}</h1><p class="lead">${bi(p.summary)}</p>${actionRow('person',id)}<div class="box warning"><h3>${B('特别辨析','注意して区別すること')}</h3><p>${bi(p.focus)}</p></div>${rs.length?`<section class="article-section"><h2>${B('相关人物与机构','関連人物・機関')}</h2>${relationGraph(rs)}</section>`:''}<section class="article-section"><h2>${B('关联年代','関連年代')}</h2><div class="event-list">${ev.map(eventCard).join('')}</div></section><section class="article-section"><h2>${B('关联地点','関連地点')}</h2><div class="placegrid">${p.places.map(i=>placeCard(get('places',i))).join('')}</div></section><section class="article-section"><h2>${B('参考依据','参考資料')}</h2>${p.refs.map(i=>sourceItem(get('sources',i))).join('')}</section>${completion('person',id)}</article>`;}
function studies(){return `<div class="titlebar"><div><div class="eyebrow">HISTORICAL INQUIRY</div><h1>${B('历史问题研究室','歴史の問いを考える')}</h1><p>${B('先解释发生了什么，再讨论证据、机制与解释边界。','何が起きたかを理解し、証拠・仕組み・解釈の限界へ進む。')}</p></div></div><div class="grid2 studycards">${DATA.studies.map(studyCard).join('')}</div>`;}
function studyPage(id){const s=get('studies',id);if(!s)return notfound();const allRefs=[...new Set(s.sections.flatMap(x=>x.refs))];return `<div class="crumb">${link(t('问题研究室','問いを考える'),'studies','')} / ${bi(s.title)}</div><div class="article-layout">${articleOutline(s.sections.map((x,i)=>['sec'+i,plain(x.title)]).concat([['references',t('参考资料','参考資料')]]))}<article class="article"><div class="eyebrow">CLOSE READING / ${s.sections.length} ${t('节','節')}</div><h1>${bi(s.title)}</h1><p class="lead">${bi(s.lead)}</p>${actionRow('study',id)}${diagram(s.diagram)}${s.sections.map((sec,i)=>`<section id="sec${i}" class="article-section"><div class="tagrow">${badge(({context:pair('历史背景','歴史的背景'),evidence:pair('材料所见','資料に見えること'),method:pair('阅读方法','読む方法'),analysis:pair('编辑分析','編集上の分析')})[sec.kind],sec.kind==='evidence'?'direct':'context')}</div><h2><span class="sectionno">${i+1}</span>${bi(sec.title)}</h2><p class="bodytext">${bi(sec.text)}</p>${refs(sec.refs)}</section>`).join('')}<div class="box task"><h3>${B('形成自己的回答','自分の回答へ')}</h3><p>${bi(s.question)}</p>${button(B('记录判断、证据与疑问','判断・証拠・問いを記録'),'note',`data-type="study" data-id="${id}"`,'small')}</div><section class="article-section"><h2>${B('地点之间的连接','場所のつながり')}</h2><div class="actions">${s.places.map(i=>link(bi(get('places',i).title),'place/'+i,'btn small')).join('')}${s.people.map(i=>link(bi(get('people',i).title),'person/'+i,'btn small')).join('')}</div></section><section class="article-section" id="references"><h2>${B('参考资料及用途','参考資料と用途')}</h2>${allRefs.map(i=>sourceItem(get('sources',i))).join('')}</section>${completion('study',id)}</article></div>`;}
function caseCard(c){const s=get('sources',c.source);const a=state.answers[c.id];return `<article class="card casecard" id="case-${c.id}"><h3>${bi(c.title)}</h3><dl class="source-meta"><dt>${B('事件时间','出来事の時点')}</dt><dd>${esc(c.eventDate)}</dd><dt>${B('材料层次','資料の層')}</dt><dd>${bi(c.objectDate)}</dd><dt>${B('所用入口','資料への入口')}</dt><dd>${external(s.url,esc(s.org))}</dd></dl><p class="hint">${bi(s.use)}</p><div class="box" style="margin-top:17px"><h3>${B('先判断，再看解释','判断してから解説を見る')}</h3><p>${bi(c.prompt)}</p></div><div class="options">${c.options.map((o,i)=>`<button class="option ${a===i?'selected':''} ${a!==undefined&&c.answer===i?'correct':''}" data-action="answer" data-id="${c.id}" data-index="${i}" aria-pressed="${a===i}">${String.fromCharCode(65+i)}. ${bi(o)}</button>`).join('')}</div>${a!==undefined?`<div class="feedback" role="status"><strong>${a===c.answer?B('判断有依据。','根拠のある判断です。'):B('再检查材料能证明的范围。','資料が証明できる範囲を確認しよう。')}</strong><p>${bi(c.explain)}</p>${button(B('重新作答','解答をやり直す'),'reset-answer',`data-id="${c.id}"`,'small')}</div>`:''}${refs(c.refs)}<div class="actions">${link(B('去相关地点阅读 →','関連地点で読む →'),'place/'+c.place,'btn small')}${button(B('把问题存入摘记','問いをノートへ'),'note',`data-type="case" data-id="${c.id}"`,'small')}</div></article>`;}
function sources(){return `<div class="titlebar"><div><div class="eyebrow">SOURCE READING ROOM</div><h1>${B('史料阅览室','史料閲覧室')}</h1><p>${B('原件入口、材料档案与五个证据判断练习。这里不把本站释义当作原文。','原資料への入口、資料情報、五つの証拠判断。本サイトの説明を原文とはしない。')}</p></div>${link(B('完整参考目录 ↓','参考資料一覧 ↓'),'references','btn')}</div><div class="box"><h3>${B('原文与翻译的边界','原文と翻訳の区別')}</h3><p>${B('当前增量没有嵌入原件高清扫描或全文转录。点击机构入口查看原件；本站双语文字为编辑导读，外交文本请使用两国官方版本。','この追加版には原件の高精細スキャンや全文翻刻を収録していない。機関のリンクで原資料を確認する。二言語本文は編集ガイドで、外交文書には両国公式版を使う。')}</p></div><div class="grid2 section">${DATA.cases.map(caseCard).join('')}</div>${diagram('object')}`;}
function referencesPage(){return `<div class="titlebar"><div><div class="eyebrow">REFERENCE DESK</div><h1>${B('资料有出处，使用有范围','資料に出典を、利用に範囲を')}</h1><p>${DATA.sources.length} ${B('条资料记录；教学设计参考与历史依据分开。','件。教育設計の参考と歴史的根拠は区別。')}</p></div></div><div class="toolbar">${selector('sourceKind',pair('材料类型','資料種類'),[['all',pair('全部','すべて')],...Object.entries(sourceKinds)],filters.sourceKind)}</div><div id="source-results" class="card"></div>`;}
function sourcePage(id){
 const source=get('sources',id);
 if(!source)return notfound();
 const places=DATA.places.filter(place=>place.refs.includes(id));
 const events=DATA.events.filter(event=>event.refs.includes(id));
 return `<article class="article" style="margin:auto">
  <div class="crumb">${link(t('参考资料目录','参考資料一覧'),'references','')}</div>
  <h1>${esc(source.title)}</h1>
  ${sourceItem(source,true)}
  ${places.length?`<section class="article-section"><h2>${B('关联地点','関連地点')}</h2><div class="placegrid">${places.map(placeCard).join('')}</div></section>`:''}
  ${events.length?`<section class="article-section"><h2>${B('关联年代','関連年代')}</h2><div class="event-list">${events.map(eventCard).join('')}</div></section>`:''}
 </article>`;
}
function updateSources(){document.getElementById('source-results').innerHTML=DATA.sources.filter(s=>filters.sourceKind==='all'||s.kind===filters.sourceKind).map(sourceItem).join('');}
function routesPage(){return `<div class="titlebar"><div><div class="eyebrow">LEARNING PATHS</div><h1>${B('不是赶景点，是追一个问题','観光地を急がず、一つの問いを追う')}</h1><p>${B('五条路径都是阅读顺序，不是步行导航；进度由你自行确认。','五つのパスは読書順序で、徒歩案内ではない。進度は自分で確認する。')}</p></div></div><div class="grid2">${DATA.routes.map(pathCard).join('')}</div>`;}
function routePage(id){const r=get('routes',id);if(!r)return notfound();const n=r.steps.filter(pid=>state.completed.includes('place:'+pid)).length;return `<div class="crumb">${link(t('学习路径','学習パス'),'routes','')}</div><article class="article" style="margin:auto"><div class="eyebrow">LEARNING PATH / ${bi(cityname(r.city))}</div><h1>${bi(r.title)}</h1><p class="lead">${bi(r.description)}</p><div class="smallmeta">${n} / ${r.steps.length} ${B('处地点已读','地点読了')}</div><div class="progress" style="margin-top:10px"><div style="width:${n/r.steps.length*100}%"></div></div><div class="route-stops">${r.steps.map(id=>{const p=get('places',id);return `<div class="route-stop"><div class="card"><div class="tagrow">${badge(relationLabels[p.relation],p.relation)}</div><h3>${bi(p.title)}</h3><p>${bi(p.summary)}</p><div class="actions">${link(B('阅读地点','地点を読む'),'place/'+id,'btn small')}${state.completed.includes('place:'+id)?badge(pair('已读','読了'),'direct'):''}</div></div></div>`;}).join('')}</div><div class="box task"><h3>${B('最后，整合成一个回答','最後に、一つの回答へ')}</h3><p>${bi(get('studies',r.study).lead)}</p>${link(B('进入深读专题 →','深読記事へ →'),'study/'+r.study,'btn primary')}</div></article>`;}
function comparePage(){state.compare=state.compare.filter(id=>get('places',id)).slice(0,3);const ps=state.compare.map(id=>get('places',id));return `<div class="titlebar"><div><div class="eyebrow">COMPARATIVE READING</div><h1>${B('用相同的问题，比较不同地点','同じ問いで、異なる場所を比べる')}</h1><p>${B('最多选择三个地点。比较说明差异，不自动证明直接影响。','三地点まで。比較は相違を示すが、直接の影響を自動的に証明しない。')}</p></div></div>${!ps.length?`<div class="empty">${B('从地点卡片点击“比较”开始。','地点カードの「比較」から開始。')}<div class="actions" style="justify-content:center">${link(B('探索西安','西安へ'),'city/xian','btn primary')}${link(B('探索北京','北京へ'),'city/beijing','btn')}</div></div>`:`<div class="compare-wrap"><table><thead><tr><th>${B('观察角度','観察の視点')}</th>${ps.map(p=>`<th class="tablehead"><h3>${link(bi(p.title),'place/'+p.id,'')}</h3>${button(B('移出','外す'),'compare',`data-id="${p.id}"`,'small')}</th>`).join('')}</tr></thead><tbody>${[[pair('时代','時代'),p=>bi(eraLabels[p.era])],[pair('材料类型','資料の種類'),p=>bi(kindLabels[p.kind])],[pair('交流关系','交流との関係'),p=>badge(relationLabels[p.relation],p.relation)],[pair('中心问题','中心の問い'),p=>bi(p.summary)],[pair('怎样观察','観察方法'),p=>bi(p.method)],[pair('不能直接推断','直接推論できないこと'),p=>bi(p.limit)],[pair('参考依据','参考根拠'),p=>refs(p.refs)]].map(([label,fn])=>`<tr><td>${bi(label)}</td>${ps.map(p=>`<td>${fn(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}<section class="section"><h2>${B('建议比较组','比較の例')}</h2><div class="actions">${button(B('汉长安／唐长安／明城墙','漢長安／唐長安／明城壁'),'compare-set','data-ids="weiyang,daming,wall"')}${button(B('碑林／北京国子监','碑林／北京国子監'),'compare-set','data-ids="beilin,guozijian"')}${button(B('青龙寺／外交文件／医院','青龍寺／外交文書／病院'),'compare-set','data-ids="qinglong,hall,hospital"')}</div></section>`;}
const typeToCollection={place:'places',person:'people',event:'events',study:'studies',case:'cases'};
function entity(type,id){return get(typeToCollection[type]||'',id);}
function noteKey(type,id){return type+':'+id;}
function ensureNote(type,id){const item=entity(type,id);if(!item)return null;const key=noteKey(type,id);if(!state.notes[key]){state.notes[key]={type,id,title:item.title,claim:'',evidence:'',question:plain(item.question||item.prompt||item.summary||pair('','')),refs:[...new Set(item.refs||item.sections?.flatMap(s=>s.refs)||[])],updated:new Date().toISOString()};save();}return key;}
function notebook(type,id){let activeKey=type&&id?ensureNote(type,id):(selectedNoteKey&&state.notes[selectedNoteKey]?selectedNoteKey:Object.keys(state.notes)[0]);selectedNoteKey=activeKey;const entries=Object.entries(state.notes);const n=state.notes[activeKey];const read=state.completed.length,marks=state.bookmarks.length;return `<div class="titlebar"><div><div class="eyebrow">MY STUDY DESK</div><h1>${B('把读过的，变成自己的理解','読んだことを、自分の理解へ')}</h1><p>${B('判断、证据、疑问分别记录。只保存在此浏览器；导出文件才能自行备份或迁移。','判断・証拠・問いを分ける。このブラウザーのみの保存。バックアップや移行には書出しが必要。')}</p></div></div><div class="stats"><div><strong>${read}</strong><span>${B('已读','読了')}</span></div><div><strong>${marks}</strong><span>${B('收藏','保存')}</span></div><div><strong>${entries.length}</strong><span>${B('摘记','ノート')}</span></div></div><div class="exportbar">${button(B('导出学习记录 JSON','学習記録JSONを書出し'),'export-json')}${button(B('导出摘记 Markdown','ノートMarkdownを書出し'),'export-md')}${button(B('导入并合并备份','バックアップを読込み・統合'),'import')}<input id="import-file" type="file" accept="application/json,.json" hidden></div>${!persistenceOK?`<div class="box warning">${B('本地保存不可用，请及时导出；关闭页面可能丢失本次记录。','ローカル保存を利用できません。ページを閉じる前に書き出してください。')}</div>`:''}<section class="section"><div class="split"><aside class="note-index">${entries.map(([key,note])=>`<button data-action="open-note" data-key="${esc(key)}" class="${key===activeKey?'active':''}">${bi(note.title)}<small style="display:block;color:var(--muted)">${esc(note.updated.slice(0,10))}</small></button>`).join('')}</aside><div>${n?`<form class="card noteform" data-notekey="${esc(activeKey)}" onsubmit="return false"><h2>${bi(n.title)}</h2><div class="tiny">${link(B('返回对应内容 ↗','関連内容に戻る ↗'),(n.type==='case'?'sources':n.type+'/'+n.id),'')} · <span class="save-status" id="save-status" role="status">${t('输入时自动保存','入力時に自動保存')}</span></div><label for="claim">${B('我的判断','自分の判断')}</label><textarea id="claim" data-note-field="claim" placeholder="${t('我认为……；哪些部分还只是推测？','私は……と考える。どこからは推測か。')}">${esc(n.claim)}</textarea><label for="evidence">${B('依据与材料位置','根拠と資料の位置')}</label><textarea id="evidence" data-note-field="evidence" placeholder="${t('材料、页码/段落、原文入口、观察到的细节……','資料・頁や段落・原文へのリンク・観察した細部……')}">${esc(n.evidence)}</textarea><label for="question">${B('仍然想知道','まだ知りたいこと')}</label><textarea id="question" data-note-field="question">${esc(n.question)}</textarea>${refs(n.refs)}<div class="tiny" style="margin-top:15px">${B('本站不会自动评分你的开放回答，也不会将它发往外部AI。','自由回答は自動採点せず、外部AIへ送信しない。')}</div></form>`:`<div class="empty">${B('在任一地点或专题点击“写一条摘记”开始。','地点や記事の「ノートを書く」から開始。')}<div class="actions" style="justify-content:center">${link(B('选择一个专题','記事を選ぶ'),'studies','btn primary')}</div></div>`}</div></div></section><section class="section"><h2>${B('我的收藏','保存した項目')}</h2><div class="actions">${state.bookmarks.length?state.bookmarks.map(key=>{const [ty,i]=key.split(':');const obj=entity(ty,i);return obj?link(bi(obj.title),(ty==='case'?'sources':ty+'/'+i),'btn small'):'';}).join(''):`<p class="hint">${B('尚无收藏。','まだありません。')}</p>`}</div></section><details class="settings"><summary>${B('练习回顾与备份规则','練習の振返りとバックアップ規則')}</summary><div><p class="hint">${B('重复导入不会覆盖同名笔记：内容不同的版本将另存为一条记录；收藏与已读取并集。旧站任何存储键均不会读取、改写或清空。','重複するノートは上書きしない。内容が異なる版は別の記録として保存。保存項目・読了は統合。旧サイトの保存キーは読取り・変更・消去しない。')}</p><div class="actions">${DATA.cases.filter(c=>state.answers[c.id]!==undefined).map(c=>link(`${state.answers[c.id]===c.answer?'✓':'↺'} ${bi(c.title)}`,'sources','btn small')).join('')}</div></div></details>`;}
function searchPage(){return `<div class="titlebar"><div><div class="eyebrow">SEARCH THE CONNECTIONS</div><h1>${B('从一个词，找到一条线索','一つの言葉から、手掛かりへ')}</h1><p>${B('检索北京、西安专题中的地点、人物、年代与深读正文。','北京・西安の特集から、地点・人物・年代・深読の本文を探せます。')}</p></div></div><div class="searchbox"><span>⌕</span><input id="global-search" type="search" autofocus placeholder="${t('试试：空海、明、1972、円珍、目录……','空海・明・1972・円珍・目録……')}" aria-label="${t('全内容搜索','全文検索')}"></div><div id="search-results" class="section"></div>`;}
function updateSearch(q){const text=q.trim().toLowerCase();const res=[];if(text)for(const [type,col]of Object.entries(typeToCollection)){for(const item of DATA[col]){if(JSON.stringify(item).toLowerCase().includes(text)){res.push({type,item});}}}const out=document.getElementById('search-results');out.innerHTML=!text?`<div class="hint">${B('中文、日文、人名和年份都可检索。','中国語・日本語・人名・年で検索できる。')}</div>`:!res.length?`<div class="empty">${B('没有结果。可尝试人物别名或更短的关键词。','該当なし。別名や短い語で試してください。')}</div>`:`<div class="hint">${res.length} ${B('条结果','件')}</div><div class="event-list" style="margin-top:15px">${res.map(({type,item})=>`<a href="#${type==='case'?'sources':type+'/'+item.id}" class="event-row"><div>${badge(({place:pair('地点','地点'),person:pair('人物','人物'),event:pair('年代','年代'),study:pair('深读','深読'),case:pair('史料练习','史料練習')})[type])}</div><div><h3>${bi(item.title)}</h3><p>${bi(item.summary||item.lead||item.prompt||pair('',''))}</p></div></a>`).join('')}</div>`;}
function about(){return `<article class="article" style="margin:auto"><div class="eyebrow">BEIJING / XI’AN</div><h1>${B('关于城市探索','都市特集について')}</h1><section class="article-section"><h2>${B('内容与编辑标准','内容と編集基準')}</h2><p class="bodytext">${bi(DATA.notes.editorial)}</p><div class="stats">${[['places','地点','地点'],['events','年代节点','年代項目'],['people','人物','人物'],['studies','深读','深読'],['sources','参考资料','参考資料']].map(([k,z,j])=>`<div><strong>${DATA[k].length}</strong><span>${B(z,j)}</span></div>`).join('')}</div></section><section class="article-section"><h2>${B('已纠正的历史表达','訂正した歴史表現')}</h2><div class="event-list">${[[pair('空海入唐：中唐','空海の入唐：中唐'),pair('不再写成盛唐向中唐过渡。','盛唐から中唐への移行期とはしない。'),['kukai']],[pair('圆仁与宗叡：所属不是活动地','円仁と宗叡：所属と活動地を分ける'),pair('扬州指导与西明寺归属分别表述；圆珍另立人物和855年目录。','揚州での指導と西明寺所属を区別。円珍と855年の目録は別に扱う。'),['ennin','enchin']],[pair('1945华北受降：太和殿广场','1945年華北降伏受領：太和殿前広場'),pair('不把广场写成殿内某间房。','広場を殿内の特定室としない。'),['surrender']],[pair('条约签署与生效分开','条約署名と発効を分ける'),pair('1978年8月12日签署；10月23日生效。','1978年8月12日署名、10月23日発効。'),['treaty','normalization']]].map(([title,text,rs])=>`<div class="card"><h3>${bi(title)}</h3><p class="hint">${bi(text)}</p>${refs(rs)}</div>`).join('')}</div></section><section class="article-section"><h2>${B('图像与网络','画像とネットワーク')}</h2><p class="bodytext">${bi(DATA.notes.images)}</p><div class="settings"><label class="photo-setting"><input type="checkbox" id="photo-toggle" ${state.photos?'checked':''}><span>${B('显示实景照片','現地写真を表示する')}<br><span class="hint">${B('失败时仍能阅读示意图与正文；照片不是唐代原貌。','失敗時も模式図・本文を利用可能。写真は唐代の原状ではない。')}</span></span></label></div>${DATA.images.map(im=>`<div class="sourceitem"><h3>${bi(im.title)}</h3><p>${esc(im.creator)} · ${esc(im.date)} · ${external(im.licenseUrl,esc(im.license))} · ${im.embedded?B('站内图片','サイト内の画像'):B('在线图片','オンライン画像')}</p>${external(im.page,t('原图、作者与许可页','原画像・著作者・許諾'))}</div>`).join('')}</section><section class="article-section"><h2>${B('从类似网站借鉴了什么','参考サイトから取り入れたこと')}</h2>${['mit','met','jacar','digitalpalace'].map(id=>sourceItem(get('sources',id))).join('')}</section><section class="article-section"><h2>${B('保存、隐私与迁移','保存・プライバシー・移行')}</h2><p class="bodytext">${B('城市专题的收藏、进度和摘记保存在当前浏览器，可在摘记页导出。主站学习桌仍可从主站导航进入。','都市特集の保存項目・進捗・ノートはこのブラウザーに保存され、ノート画面から書き出せます。メインサイトの学習ノートはメインナビゲーションから開けます。')}</p></section></article>`;}
function notfound(){return `<div class="empty"><h1>${B('没有找到这个条目','項目が見つかりません')}</h1><p>${B('请从城市专题入口选择一个条目。','都市特集の入口から項目を選んでください。')}</p><div class="actions" style="justify-content:center">${link(B('返回入口','入口へ'),'home','btn primary')}</div></div>`;}
function render(){const [r,id,x]=route();document.documentElement.lang=state.lang==='ja'?'ja':'zh-CN';document.body.classList.toggle('dual',state.lang==='dual');document.getElementById('header').innerHTML=head();document.getElementById('footer').innerHTML=footer();let html;switch(r){case'home':html=home();break;case'city':html=city(id);break;case'place':html=place(id);break;case'timeline':html=timeline(id);break;case'event':html=eventPage(id);break;case'people':html=people();break;case'person':html=personPage(id);break;case'studies':html=studies();break;case'study':html=studyPage(id);break;case'sources':html=sources();break;case'references':html=referencesPage();break;case'source':html=sourcePage(id);break;case'routes':html=routesPage();break;case'route':html=routePage(id);break;case'compare':html=comparePage();break;case'notebook':html=notebook(id,x);break;case'search':html=searchPage();break;case'about':html=about();break;default:html=notfound();}document.getElementById('main').innerHTML=html;document.getElementById('main').dataset.route=route().join('/');if(r==='city'&&['xian','beijing'].includes(id))updatePlaces(id);if(r==='timeline')updateTimeline();if(r==='references')updateSources();if(r==='search'){document.getElementById('global-search').value=searchQuery;updateSearch(searchQuery);}document.title=(document.querySelector('main h1')?.innerText.replace(/\n/g,' · ')||t('跨海的历史','海をわたる歴史'))+' | 城市探索 06';document.querySelectorAll('[data-photo]').forEach(img=>{
 const showFallback=()=>{
  const im=get('images',img.dataset.photo);
  img.parentElement.innerHTML=placeSymbol(DATA.places.find(p=>p.image===im.id)||DATA.places[0])+`<div class="hint" style="padding:8px 16px">${B('照片未能加载，显示学习意象图。','写真を読み込めないため、学習イメージを表示。')}</div>`;
 };
 img.addEventListener('error',showFallback,{once:true});
 if(img.complete&&!img.naturalWidth)showFallback();
});}
function rerenderKeepScroll(){const y=scrollY;render();window.scrollTo(0,y);}
function toggleIn(arr,key){const i=arr.indexOf(key);if(i>=0)arr.splice(i,1);else arr.push(key);}
function download(name,text,mime){const blob=new Blob([text],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function exportJson(){download('cross-sea-city-learning.json',JSON.stringify({app:'cross-sea-city-atlas',schemaVersion:1,exported:new Date().toISOString(),bookmarks:state.bookmarks,completed:state.completed,notes:state.notes,answers:state.answers},null,2),'application/json;charset=utf-8');}
function exportMarkdown(){const lines=['# 跨海的历史 · 城市学习摘记','',`导出时间：${new Date().toISOString()}`,'','> 本地个人记录；本站导读不等于史料原文。',''];for(const [key,n] of Object.entries(state.notes)){lines.push(`## ${n.title.zh} / ${n.title.ja}`,'',`记录：${key} · ${n.updated}`,'','### 我的判断 / 判断',n.claim||'（未填写）','','### 依据 / 根拠',n.evidence||'（未填写）','','### 疑问 / 問い',n.question||'（未填写）','','### 参考入口 / 参考資料',...n.refs.filter(id=>get('sources',id)).map(id=>{const s=get('sources',id);return `- ${s.org}：${s.title} — ${s.url}`;}),'','---','');}download('cross-sea-city-notes.md',lines.join('\n'),'text/markdown;charset=utf-8');}
function safeText(s,max=20000){if(typeof s!=='string'||s.length>max)throw Error(t('备份中有不合法或过长的文本。','不正または長すぎるテキストです。'));return s;}
function validateRecordKey(k){const parts=k.split(':');return parts.length===2&&!!entity(parts[0],parts[1]);}
async function importFile(file){try{if(!file||file.size>2*1024*1024)throw Error(t('仅支持2MB以内的本站JSON备份。','本アプリの2MB以下のJSONのみ対応。'));const raw=JSON.parse(await file.text());if(raw.app!=='cross-sea-city-atlas'||raw.schemaVersion!==1)throw Error(t('不是受支持的城市学习备份格式。','対応する学習バックアップ形式ではありません。'));if(!raw.notes||typeof raw.notes!=='object'||Array.isArray(raw.notes)||Object.keys(raw.notes).length>200)throw Error(t('笔记记录不合法或超过200条。','ノートが不正または200件を超えています。'));const sanitized={};for(const [k,n] of Object.entries(raw.notes)){if(!/^[a-z0-9:_-]{1,150}$/i.test(k)||!n||!entity(n.type,n.id))throw Error(t('笔记指向不存在的条目。','存在しない項目へのノートです。'));const obj=entity(n.type,n.id);const canonical=n.type+':'+n.id;if(k!==canonical&&!k.startsWith(canonical+':import-'))throw Error('Invalid note key');sanitized[k]={type:n.type,id:n.id,title:obj.title,claim:safeText(n.claim),evidence:safeText(n.evidence),question:safeText(n.question),refs:Array.isArray(n.refs)?n.refs.filter(id=>get('sources',id)).slice(0,50):[],updated:typeof n.updated==='string'&&!isNaN(Date.parse(n.updated))?n.updated:new Date().toISOString()};}
 const pending=JSON.parse(JSON.stringify(state));let added=0;for(const [k,n] of Object.entries(sanitized)){if(!pending.notes[k]){pending.notes[k]=n;added++;}else{const old=pending.notes[k];if(['claim','evidence','question'].some(f=>old[f]!==n[f])){const duplicate=Object.values(pending.notes).some(x=>x.type===n.type&&x.id===n.id&&['claim','evidence','question'].every(f=>x[f]===n[f]));if(!duplicate){let key=k+':import-'+Date.now();while(pending.notes[key])key+='x';pending.notes[key]=n;added++;}}}}
 for(const k of ['bookmarks','completed']){if(raw[k]!==undefined&&!Array.isArray(raw[k]))throw Error('Invalid collection');pending[k]=[...new Set([...pending[k],...(raw[k]||[]).filter(x=>typeof x==='string'&&validateRecordKey(x))])];}if(raw.answers&&typeof raw.answers==='object')for(const [id,a]of Object.entries(raw.answers)){const c=get('cases',id);if(c&&Number.isInteger(a)&&a>=0&&a<c.options.length&&pending.answers[id]===undefined)pending.answers[id]=a;}
 if(Object.keys(pending.notes).length>200)throw Error(t('合并后超过200条，请先自行整理备份。','統合後200件を超えます。先にバックアップを整理してください。'));state=pending;save();go('notebook');toast(t(`已合并，新增${added}条记录；原记录保留。`,`統合完了。${added}件追加、元の記録は保持。`));}catch(err){toast(t('导入未执行：','読込み未実行：')+err.message);}}
document.addEventListener('click',ev=>{if(ev.target.closest('.skip')){ev.preventDefault();document.getElementById('main').focus();document.getElementById('main').scrollIntoView();return;}const scroll=ev.target.closest('[data-scroll]');if(scroll){ev.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return;}const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id,type=el.dataset.type;switch(a){case'lang':state.lang=el.dataset.value;save();if(initialLanguage)history.replaceState(history.state,'',location.pathname+location.hash);rerenderKeepScroll();break;case'bookmark':toggleIn(state.bookmarks,type+':'+id);save();rerenderKeepScroll();break;case'compare':if(!state.compare.includes(id)&&state.compare.length>=3){toast(t('最多比较三个地点，请先移出一个。','比較は三地点まで。一つ外してください。'));break;}toggleIn(state.compare,id);save();rerenderKeepScroll();toast(t('比较清单已更新，可进入“地点比较”。','比較リスト更新。「場所を比較」から確認。'));break;case'compare-set':state.compare=el.dataset.ids.split(',').filter(i=>get('places',i)).slice(0,3);save();go('compare');break;case'note':ensureNote(type,id);go('notebook/'+type+'/'+id);break;case'open-note':if(state.notes[el.dataset.key]){selectedNoteKey=el.dataset.key;go('notebook');}break;case'photos':state.photos=true;save();rerenderKeepScroll();break;case'diagram':{const box=el.closest('[data-diagram]');const n=diagramData[el.dataset.kind].nodes[Number(el.dataset.index)];box.querySelector('.dreadout').innerHTML=B(n[3],n[4]);box.querySelectorAll('.dnode').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',String(b===el));});break;}case'answer':state.answers[id]=Number(el.dataset.index);save();{const old=document.getElementById('case-'+id);old.outerHTML=caseCard(get('cases',id));}break;case'reset-answer':delete state.answers[id];save();document.getElementById('case-'+id).outerHTML=caseCard(get('cases',id));break;case'print':window.print();break;case'export-json':exportJson();break;case'export-md':exportMarkdown();break;case'import':document.getElementById('import-file').click();break;}});
document.addEventListener('change',ev=>{const el=ev.target;if(el.dataset.filter){filters[el.dataset.filter]=el.value;const [r,id]=route();if(r==='city')updatePlaces(id);if(r==='timeline')updateTimeline();if(r==='references')updateSources();}if(el.dataset.complete){toggleIn(state.completed,el.dataset.complete);save();toast(t('阅读记录已更新。','読書記録を更新しました。'));}if(el.id==='photo-toggle'){state.photos=el.checked;save();}if(el.id==='import-file')importFile(el.files[0]);});
document.addEventListener('input',ev=>{const el=ev.target;if(el.id==='place-search'){filters.placeQ=el.value;updatePlaces(route()[1]);}if(el.id==='timeline-search'){filters.timeQ=el.value;updateTimeline();}if(el.id==='global-search'){searchQuery=el.value;updateSearch(el.value);}if(el.dataset.noteField){const key=el.closest('[data-notekey]').dataset.notekey;const n=state.notes[key];if(n){if(el.value.length>20000){el.value=el.value.slice(0,20000);toast(t('每栏最多20000字。','各欄20000文字まで。'));}n[el.dataset.noteField]=el.value;n.updated=new Date().toISOString();const ok=save();document.getElementById('save-status').textContent=ok?t('已保存到当前浏览器','このブラウザーに保存済み'):t('未能持久保存，请导出','永続保存できません。書き出してください。');}}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);document.getElementById('main').focus({preventScroll:true});});
render();
